/// Q2 compares independently rebuilt payloads to these frozen Q1 literals without making the
/// Q1 fixture constructor an expected-byte authority.
pub(super) fn explicit_abort_sections_literal_for_q2() -> [Vec<u8>; 7] {
    std::array::from_fn(|ordinal| decode_hex(Q1_EXPLICIT_ABORT_SECTION_HEX[ordinal]))
}

/// Q2 compares independently rebuilt payloads to these frozen Q1 literals without making the
/// Q1 fixture constructor an expected-byte authority.
pub(super) fn successful_sections_literal_for_q2() -> [Vec<u8>; 7] {
    std::array::from_fn(|ordinal| decode_hex(Q1_SUCCESS_SECTION_HEX[ordinal]))
}

pub(super) fn explicit_abort_s7_section_root_literal_for_q2() -> [u8; 32] {
    super::decode_hex(Q1_EXPLICIT_ABORT_SECTION_ROOTS_HEX[6])
        .try_into()
        .expect("Q1 explicit S7 root literal width")
}

pub(super) fn successful_s7_section_root_literal_for_q2() -> [u8; 32] {
    super::decode_hex(Q1_SUCCESS_SECTION_ROOTS_HEX[6])
        .try_into()
        .expect("Q1 successful S7 root literal width")
}

