    write_u32(&mut token, 16, display_oid);
    write_u32(&mut token, 20, table_ref);
    write_u64(&mut token, 24, generation);
    write_u64(&mut token, 32, floor);
    write_u32(&mut token, 40, Q1_ABSENT);
