fn statement_disposition_root(statement: u32, rows: &[Q1Row]) -> [u8; 32] {
    let mut digest = Sha256::new();
    let domain = b"gpu-db/write001/s7-statement-dispositions/v2";
    digest.update((domain.len() as u64).to_le_bytes());
    digest.update(domain);
    digest.update(statement.to_le_bytes());
    digest.update((rows.len() as u32).to_le_bytes());
    for row in rows {
        digest.update(s4_bytes(*row));
    }
    digest.finalize().into()
}

fn statement_sequence_root(statement: u32, entries: &[Vec<u8>]) -> [u8; 32] {
    let mut digest = Sha256::new();
    let domain = b"gpu-db/write001/s7-statement-sequences/v2";
    digest.update((domain.len() as u64).to_le_bytes());
    digest.update(domain);
    digest.update(statement.to_le_bytes());
    digest.update((entries.len() as u32).to_le_bytes());
    for entry in entries {
        digest.update(entry);
    }
    digest.finalize().into()
}

fn statement_dependency_root(statement: u32, uses: &[u8], token_digests: &[[u8; 32]]) -> [u8; 32] {
    let mut digest = Sha256::new();
    let domain = b"gpu-db/write001/s7-statement-dependencies/v2";
    digest.update((domain.len() as u64).to_le_bytes());
    digest.update(domain);
    digest.update(statement.to_le_bytes());
    digest.update((uses.len() as u32 / 32).to_le_bytes());
    for use_bytes in uses.chunks_exact(32) {
        digest.update(use_bytes);
        let dependency = u32::from_le_bytes(use_bytes[4..8].try_into().expect("use ref width"));
        digest.update(token_digests[dependency as usize]);
    }
    digest.finalize().into()
}

fn statement_projection_root(statement: u32, projections: &[Q1Projection]) -> [u8; 32] {
    let mut digest = Sha256::new();
    let domain = b"gpu-db/write001/s7-statement-projections/v2";
    digest.update((domain.len() as u64).to_le_bytes());
    digest.update(domain);
    digest.update(statement.to_le_bytes());
    digest.update((projections.len() as u32).to_le_bytes());
    for projection in projections {
        digest.update(projection.digest);
    }
    digest.finalize().into()
}

fn overlay_root(
    before: [u8; 32],
    statement: u32,
    typed_digest: [u8; 32],
    record_digest: [u8; 32],
    disposition_root: [u8; 32],
    sequence_root: [u8; 32],
    dependency_root: [u8; 32],
    projection_root: [u8; 32],
) -> [u8; 32] {
    v2_digest(
        b"gpu-db/write001/s7-statement-overlay-root/v2",
        &[
            &before,
            &statement.to_le_bytes(),
            &typed_digest,
            &record_digest,
            &disposition_root,
            &sequence_root,
            &dependency_root,
            &projection_root,
        ],
    )
}

fn image_descriptor(image: &[u8]) -> (Vec<u8>, [u8; 32], [u8; 32]) {
    let layout: [u8; 32] = image[64..96].try_into().expect("image layout width");
    let content = v2_digest(
        b"gpu-db/write001/s7-image-content/v2",
        &[&(image.len() as u64).to_le_bytes(), image],
    );
    let mut descriptor = vec![0; 160];
    write_u32(&mut descriptor, 0, 0);
    write_u32(&mut descriptor, 4, 0);
    write_u32(&mut descriptor, 8, 1);
    write_u32(&mut descriptor, 16, 0);
    write_u32(
        &mut descriptor,
        20,
        u32::from_le_bytes(image[28..32].try_into().expect("image columns width")),
    );
    write_u64(&mut descriptor, 24, 0);
    write_u64(&mut descriptor, 32, image.len() as u64);
    descriptor[64..96].copy_from_slice(&layout);
    descriptor[96..128].copy_from_slice(&content);
    let digest = v2_digest(
        b"gpu-db/write001/s7-image-descriptor/v2",
        &[&descriptor[..128], &[0; 32]],
    );
    descriptor[128..160].copy_from_slice(&digest);
    (descriptor, layout, content)
}

