fn q1_success_sources() -> (crate::Engine, [Vec<u8>; 3]) {
    let engine = crate::Engine::new_local();
    engine
        .execute_text(
            1,
            "CREATE TABLE q1_parent (id int4 PRIMARY KEY, key_a int4, key_b int4, note text, UNIQUE (key_a, key_b))",
        )
        .expect("Q1 parent table creates");
    engine
        .execute_text(
            2,
            "CREATE TABLE q1_child (id serial PRIMARY KEY, parent_id int4, key_a int4, key_b int4, note text, UNIQUE (key_a, key_b))",
        )
        .expect("Q1 child table creates");
    engine
        .execute_text(
            3,
            "ALTER TABLE ONLY q1_child ADD CONSTRAINT q1_child_parent_fk FOREIGN KEY (parent_id) REFERENCES q1_parent(id)",
        )
        .expect("Q1 child foreign-key creates");
    let a_first = typed_record(
        &engine,
        "INSERT INTO q1_parent (id, key_a, key_b, note) VALUES (1, 10, 20, 'alpha') RETURNING note, id, note",
        0,
        Q1_TXN,
        false,
    );
    let b_middle = typed_record(
        &engine,
        "INSERT INTO q1_child (parent_id, key_a, key_b, note) VALUES (1, NULL, 30, 'beta') RETURNING note, id, note",
        1,
        Q1_TXN,
        true,
    );
    let a_last = typed_record(
        &engine,
        "INSERT INTO q1_parent (id, key_a, key_b, note) VALUES (2, NULL, 40, 'gamma') RETURNING note, id, note",
        2,
        Q1_TXN,
        false,
    );
    (engine, [a_first, b_middle, a_last])
}

