#[test]
fn q1_success_sources_hold_interleaved_index_fk_and_returning_facts() {
    let (_, sources) = q1_success_sources();
    let a_first = decode_record(&sources[0]);
    let b_middle = decode_record(&sources[1]);
    let a_last = decode_record(&sources[2]);
    assert_eq!(a_first.facts().target, a_last.facts().target);
    assert_ne!(a_first.facts().target, b_middle.facts().target);
    assert_eq!(
        a_first.indexes().len(),
        2,
        "parent primary + composite unique"
    );
    assert_eq!(
        b_middle.indexes().len(),
        2,
        "child primary + composite unique"
    );
    assert_eq!(b_middle.foreign_keys().len(), 1, "child FK is retained");
    assert_eq!(
        b_middle.sequence_effects().len(),
        1,
        "serial default is published"
    );
    assert_eq!(a_first.returning_projections().len(), 3);
    assert_eq!(b_middle.returning_projections().len(), 3);
    assert_eq!(a_last.returning_projections().len(), 3);
}

#[test]
fn q1_codec_closure_has_only_the_cfg_test_bridge_and_v1_writer() {
    let facade = include_str!("../../semantics_v2.rs");
    let retained = include_str!("../retained.rs");
    let codec = include_str!("../../codec.rs");
    assert!(facade.contains("#[cfg(test)]\nfn close_canonical_semantics_v2_for_test"));
    assert!(
        facade.contains("#[cfg(test)]\nfn codec_closed_canonical_semantics_v2_for_test"),
        "the Q2 owner handoff remains cfg(test)-only"
    );
    assert_eq!(
        facade.matches("close_codec_for_test").count(),
        2,
        "only the discard bridge and Q2 owner handoff may close codec state"
    );
    assert!(!facade.contains("pub(super) fn close_canonical_semantics_v2"));
    assert!(!facade.contains("pub fn codec_closed_canonical_semantics_v2"));
    assert_eq!(
        retained.matches("close_codec(").count(),
        4,
        "one definition, its cfg(test) bridge call, and sealed live/historical catalog handoffs"
    );
    assert!(retained.contains("#[cfg(test)]\n    pub(super) fn close_codec_for_test"));
    let encoder = codec
        .split("fn encoded_headers")
        .nth(1)
        .and_then(|tail| tail.split("fn aggregate_status_roots").next())
        .expect("codec keeps its bounded aggregate header encoder");
    assert!(encoder.contains("writer.u16(AGGREGATE_SEMANTICS_V1)?"));
    assert!(!encoder.contains("AGGREGATE_SEMANTICS_V2"));
}

#[test]
fn q1_successful_a_b_a_interleave_closes_indexes_fk_and_mixed_returning() {
    let fixture = successful_a_b_a_fixture();
    for (index, (actual, expected)) in fixture
        .sections
        .iter()
        .zip(Q1_SUCCESS_SECTION_HEX)
        .enumerate()
    {
        assert!(
            expected.len().is_multiple_of(2),
            "frozen A/B/A S{} stays byte-aligned",
            index + 1
        );
        assert_eq!(
            actual,
            &decode_hex(expected),
            "frozen A/B/A S{} bytes drifted",
            index + 1
        );
    }
    assert_eq!(
        fixture.status,
        decode_hex(Q1_SUCCESS_STATUS_HEX),
        "frozen A/B/A STATUS2"
    );
    for (actual, expected) in fixture
        .section_roots
        .iter()
        .zip(Q1_SUCCESS_SECTION_ROOTS_HEX)
    {
        assert_eq!(
            *actual,
            digest_literal(expected),
            "frozen A/B/A section root"
        );
    }
    assert_eq!(
        fixture.aggregate_root,
        digest_literal(Q1_SUCCESS_AGGREGATE_ROOT_HEX)
    );
    assert_eq!(
        fixture.root_descriptor,
        digest_literal(Q1_SUCCESS_ROOT_DESCRIPTOR_HEX)
    );
    assert_eq!(
        fixture.payload_digest,
        digest_literal(Q1_SUCCESS_PAYLOAD_HEX)
    );
    assert_eq!(
        fixture.table_manifest,
        digest_literal(Q1_SUCCESS_MANIFEST_HEX)
    );
    assert_eq!(
        fixture.overlay_after,
        digest_literal(Q1_SUCCESS_OVERLAY_HEX)
    );
    assert_eq!(
        fixture.outcome.returning_digest,
        digest_literal(Q1_SUCCESS_RESPONSE_ROOT_HEX)
    );
    let s7 = &fixture.sections[6];
    let at = |ordinal: usize| {
        u64::from_le_bytes(
            s7[104 + ordinal * 16..112 + ordinal * 16]
                .try_into()
                .expect("Q1 S7 directory"),
        ) as usize
    };
    assert_eq!(s7.len(), 17_236, "frozen A/B/A S7 length");
    assert_eq!(
        &s7[104..328],
        decode_hex(Q1_SUCCESS_S7_DIRECTORY_HEX),
        "frozen A/B/A S7 directory geometry"
    );
    assert_eq!(&s7[568..600], digest_literal(Q1_SUCCESS_PAYLOAD_HEX));
    assert_eq!(
        &s7[at(5) + 304..at(5) + 336],
        digest_literal(Q1_SUCCESS_INDEX_DESCRIPTOR_HEX)
    );
    assert_eq!(
        &s7[at(7) + 128..at(7) + 160],
        digest_literal(Q1_SUCCESS_TRANSITION_HEX)
    );
    assert_eq!(
        &s7[at(8) + 96..at(8) + 128],
        digest_literal(Q1_SUCCESS_TYPED_KEY_HEX)
    );
    assert_eq!(
        &s7[at(3) + 192..at(3) + 224],
        digest_literal(Q1_SUCCESS_DEPENDENCY_HEX)
    );
    assert_eq!(
        &s7[at(11) + 96..at(11) + 128],
        digest_literal(Q1_SUCCESS_IMAGE_CONTENT_HEX)
    );
    assert_eq!(
        &fixture.sections[5][104..136],
        digest_literal(Q1_SUCCESS_LOGICAL_RETURNING_HEX)
    );
    let fragments = [
        gpu_db_wal::CanonicalFragmentRef {
            kind: gpu_db_wal::CanonicalFragmentKind::RowMutation,
            body: &fixture.fragment_body,
        },
        gpu_db_wal::CanonicalFragmentRef {
            kind: gpu_db_wal::CanonicalFragmentKind::TransactionClaimStatus,
            body: &fixture.status,
        },
    ];
    measure_canonical_semantics_v2(&fixture.outer, &fixture.outcome, &fragments)
        .expect("Q1 A/B/A passes raw framing and pass zero");
    close_canonical_semantics_v2_for_test(&fixture.outer, &fixture.outcome, &fragments)
        .expect("Q1 A/B/A closes retained rows, indexes, FK, sequence, and RETURNING");
    assert_eq!(fixture.sections[3].len(), 3 * 64);
    assert_eq!(
        fixture.sections[4].len(),
        52 + crate::ENCODED_SEQUENCE_VALUE_REFERENCE_BYTES
    );
}

#[test]
fn q1_explicit_abort_keeps_published_sequence_but_cancels_all_rows() {
    let fixture = explicit_abort_fixture();
    for (index, (actual, expected)) in fixture
        .sections
        .iter()
        .zip(Q1_EXPLICIT_ABORT_SECTION_HEX)
        .enumerate()
    {
        assert!(
            expected.len().is_multiple_of(2),
            "frozen explicit-abort S{} hex stays byte-aligned",
            index + 1
        );
        let expected_bytes = decode_hex(expected);
        assert_eq!(
            actual.len(),
            expected_bytes.len(),
            "frozen explicit-abort S{} length drifted",
            index + 1
        );
        let first_mismatch = actual
            .iter()
            .zip(&expected_bytes)
            .position(|(actual, expected)| actual != expected);
        assert!(
            first_mismatch.is_none(),
            "frozen explicit-abort S{} bytes drifted first_at={first_mismatch:?}",
            index + 1
        );
    }
    assert_eq!(
        fixture.status,
        decode_hex(Q1_EXPLICIT_ABORT_STATUS_HEX),
        "frozen STATUS2 bytes drifted"
    );
    let expected_s7 = decode_hex(Q1_EXPLICIT_ABORT_S7_HEX);
    assert_eq!(expected_s7.len(), 3_396, "frozen explicit-abort S7 length");
    assert_eq!(fixture.sections[6], expected_s7, "full S7 bytes are frozen");
    assert_eq!(
        &fixture.sections[6][104..328],
        decode_hex(Q1_EXPLICIT_ABORT_S7_DIRECTORY_HEX),
        "S7 directories retain their independently frozen geometry"
    );
    let s7 = &fixture.sections[6];
    let read_u32 = |offset| u32::from_le_bytes(s7[offset..offset + 4].try_into().unwrap());
    let read_u64 = |offset| u64::from_le_bytes(s7[offset..offset + 8].try_into().unwrap());
    let resolutions_at = read_u64(104 + 2 * 16) as usize;
    let dependencies_at = read_u64(104 + 3 * 16) as usize;
    let uses_at = read_u64(104 + 4 * 16) as usize;
    let ordinary = dependencies_at + 2 * 224;
    let terminal = dependencies_at + 3 * 224;
    assert_eq!(
        u16::from_le_bytes(s7[ordinary + 6..ordinary + 8].try_into().unwrap()),
        0,
        "first-statement NOT NULL guard is ordinary"
    );
    assert_eq!(
        u16::from_le_bytes(s7[terminal + 6..terminal + 8].try_into().unwrap()),
        2,
        "second-statement NOT NULL guard is terminal"
    );
    assert_eq!(
        &s7[ordinary + 160..ordinary + 192],
        &s7[terminal + 160..terminal + 192],
        "ordinary and terminal guards identify the same catalog constraint"
    );
    assert_eq!(
        (read_u32(resolutions_at + 40), read_u32(resolutions_at + 44)),
        (0, 2)
    );
    assert_eq!(
        (
            read_u32(resolutions_at + 320 + 40),
            read_u32(resolutions_at + 320 + 44),
            read_u32(resolutions_at + 320 + 84),
        ),
        (2, 3, 3),
        "second resolution seals only terminal dependency #3"
    );
    let uses: Vec<_> = (0..5)
        .map(|ordinal| {
            let use_at = uses_at + ordinal * 32;
            (
                read_u32(use_at),
                read_u32(use_at + 4),
                u16::from_le_bytes(s7[use_at + 8..use_at + 10].try_into().unwrap()),
                read_u32(use_at + 12),
            )
        })
        .collect();
    assert_eq!(
        uses,
        vec![
            (0, 0, 1, 0),
            (0, 2, 9, 1),
            (1, 0, 1, 0),
            (1, 1, 8, 0),
            (1, 3, 9, 1)
        ],
        "every catalog dependency has its exact statement/role/source witness"
    );
    for (actual, expected) in fixture
        .section_roots
        .iter()
        .zip(Q1_EXPLICIT_ABORT_SECTION_ROOTS_HEX)
    {
        assert_eq!(*actual, digest_literal(expected), "frozen section root");
    }
    assert_eq!(
        fixture.aggregate_root,
        digest_literal(Q1_EXPLICIT_ABORT_AGGREGATE_ROOT_HEX),
        "frozen aggregate root"
    );
    assert_eq!(
        fixture.root_descriptor,
        digest_literal(Q1_EXPLICIT_ABORT_ROOT_DESCRIPTOR_HEX),
        "frozen root descriptor"
    );
    assert_eq!(
        fixture.payload_digest,
        digest_literal(Q1_EXPLICIT_ABORT_PAYLOAD_HEX),
        "frozen payload digest"
    );
    assert_eq!(
        fixture.table_manifest,
        digest_literal(Q1_EXPLICIT_ABORT_MANIFEST_HEX),
        "frozen table manifest"
    );
    assert_eq!(
        fixture.overlay_after,
        digest_literal(Q1_EXPLICIT_ABORT_OVERLAY_HEX),
        "frozen terminal overlay"
    );
    let fragments = [
        gpu_db_wal::CanonicalFragmentRef {
            kind: gpu_db_wal::CanonicalFragmentKind::RowMutation,
            body: &fixture.fragment_body,
        },
        gpu_db_wal::CanonicalFragmentRef {
            kind: gpu_db_wal::CanonicalFragmentKind::TransactionClaimStatus,
            body: &fixture.status,
        },
    ];
    measure_canonical_semantics_v2(&fixture.outer, &fixture.outcome, &fragments)
        .expect("Q1 explicit abort passes raw framing and S7 pass zero");
    close_canonical_semantics_v2_for_test(&fixture.outer, &fixture.outcome, &fragments)
        .expect("Q1 explicit abort closes rows, durable sequence, and unchanged data roots");
    assert_eq!(fixture.sections[3].len(), 2 * 64);
    assert_eq!(
        fixture.sections[4].len(),
        52 + crate::ENCODED_SEQUENCE_VALUE_REFERENCE_BYTES
    );
    assert_eq!(fixture.sections[6][64..72], 0_u64.to_le_bytes());
    assert_eq!(fixture.sections[6][72..80], 0_u64.to_le_bytes());
}
